  | 0, 0 => iarm0_0_1RB1LB_0RC0LA_1RD0LB_1LC1RC
  | 0, 1 => iarm0_1_1RB1LB_0RC0LA_1RD0LB_1LC1RC
  | 1, 0 => iarm1_0_1RB1LB_0RC0LA_1RD0LB_1LC1RC
  | 1, 1 => iarm1_1_1RB1LB_0RC0LA_1RD0LB_1LC1RC
