Definition iarm_1RB1LC_0LC0RB_1LD0LB_1RB1LA (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1LC_0LC0RB_1LD0LB_1RB1LA
  | 1, 0 => iarm1_0_1RB1LC_0LC0RB_1LD0LB_1RB1LA
  | 2, 0 => iarm2_0_1RB1LC_0LC0RB_1LD0LB_1RB1LA
  | _, _ => iarm0_0_1RB1LC_0LC0RB_1LD0LB_1RB1LA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB1LC_0LC0RB_1LD0LB_1RB1LA : LRule :=
  mkLRule (mkC StB (mkS [S0;S1;S1] [S0;S1;S1] 1 0 []) S0 (mkS [] [] 0 0 []))
          (mkC StB (mkS [S0;S0;S0] [S0;S0;S0] 1 0 [S0;S1]) S0 (mkS [] [] 0 0 [])) 6 10.
Definition ch_farm1_0_1RB1LC_0LC0RB_1LD0LB_1RB1LA : list rstep := [RB (SWin 3);RB (SCycL 3 0);RB (SWinL 4);RB (SCycR 3);RB (SWin 3)].
