Definition iarm_1RB1RA_0LB1RC_1LD1RA_0RC0LD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1RA_0LB1RC_1LD1RA_0RC0LD
  | 0, 1 => iarm0_1_1RB1RA_0LB1RC_1LD1RA_0RC0LD
  | 1, 0 => iarm1_0_1RB1RA_0LB1RC_1LD1RA_0RC0LD
  | 1, 1 => iarm1_1_1RB1RA_0LB1RC_1LD1RA_0RC0LD
  | 2, 0 => iarm2_0_1RB1RA_0LB1RC_1LD1RA_0RC0LD
  | 2, 1 => iarm2_1_1RB1RA_0LB1RC_1LD1RA_0RC0LD
  | _, _ => iarm0_0_1RB1RA_0LB1RC_1LD1RA_0RC0LD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB1RA_0LB1RC_1LD1RA_0RC0LD : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S0;S1] [S1;S0;S1] 1 0 []))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S0;S0] [S0;S0;S0] 1 0 [S1])) 6 8.
