Definition iarm_1RB1RA_1LC1RD_0RD0LC_1LC1RA (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1RA_1LC1RD_0RD0LC_1LC1RA
  | 0, 1 => iarm0_1_1RB1RA_1LC1RD_0RD0LC_1LC1RA
  | 1, 0 => iarm1_0_1RB1RA_1LC1RD_0RD0LC_1LC1RA
  | 1, 1 => iarm1_1_1RB1RA_1LC1RD_0RD0LC_1LC1RA
  | 2, 0 => iarm2_0_1RB1RA_1LC1RD_0RD0LC_1LC1RA
  | 2, 1 => iarm2_1_1RB1RA_1LC1RD_0RD0LC_1LC1RA
  | _, _ => iarm0_0_1RB1RA_1LC1RD_0RD0LC_1LC1RA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

