Definition iarm_1RB1RB_0LB1RC_1LD1RA_0RC0LD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1RB_0LB1RC_1LD1RA_0RC0LD
  | 0, 1 => iarm0_1_1RB1RB_0LB1RC_1LD1RA_0RC0LD
  | 1, 0 => iarm1_0_1RB1RB_0LB1RC_1LD1RA_0RC0LD
  | 1, 1 => iarm1_1_1RB1RB_0LB1RC_1LD1RA_0RC0LD
  | 2, 0 => iarm2_0_1RB1RB_0LB1RC_1LD1RA_0RC0LD
  | 2, 1 => iarm2_1_1RB1RB_0LB1RC_1LD1RA_0RC0LD
  | _, _ => iarm0_0_1RB1RB_0LB1RC_1LD1RA_0RC0LD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

