  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1RB_0LB1RC_1LD1RA_0RC0LD | exact ok_iarm2_0_1RB1RB_0LB1RC_1LD1RA_0RC0LD]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1RB_0LB1RC_1LD1RA_0RC0LD | exact ok_iarm2_1_1RB1RB_0LB1RC_1LD1RA_0RC0LD]. }
